package net.j5os.chaoscontrol;
import android.Manifest;
import android.app.*;
import android.bluetooth.*;
import android.bluetooth.le.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.widget.*;
import java.util.*;
public class BluetoothActivity extends Activity {
 BluetoothAdapter bt; LinearLayout body,devices; TextView status; boolean registered=false; final Map<String,BluetoothDevice> seen=new LinkedHashMap<>(); final List<AdvertiseCallback> ads=new ArrayList<>();
 final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(BluetoothDevice.ACTION_FOUND.equals(i.getAction())){BluetoothDevice d=i.getParcelableExtra(BluetoothDevice.EXTRA_DEVICE);if(d!=null){seen.put(d.getAddress(),d);draw(); status.setText("Son sinyal: "+i.getShortExtra(BluetoothDevice.EXTRA_RSSI,(short)0)+" dBm");}}else if(BluetoothAdapter.ACTION_DISCOVERY_FINISHED.equals(i.getAction()))status.setText("Tarama tamamlandı: "+seen.size()+" cihaz");}};
 void button(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(0xff4488ff);l.addView(b);b.setOnClickListener(v->r.run());}
 @Override public void onCreate(Bundle b){super.onCreate(b);bt=BluetoothAdapter.getDefaultAdapter();ScrollView sc=new ScrollView(this);sc.setBackgroundColor(0xff09121f);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(16,16,16,16);sc.addView(body);setContentView(sc);status=new TextView(this);status.setTextColor(0xff4488ff);status.setTextSize(20);status.setText("BT TOOLS");body.addView(status);button(body,"Bluetooth ayarları",()->startActivity(new Intent(android.provider.Settings.ACTION_BLUETOOTH_SETTINGS)));button(body,"BT Scanner",()->scan());button(body,"BT Monitor • eşleşen cihazlar",()-> bonded());button(body,"BLE Lab • test yayını",()->advertise());button(body,"BT Messenger • TXT paylaş",()->message());button(body,"STOP ALL",()->stop());button(body,"Ana menü",()->finish());devices=new LinearLayout(this);devices.setOrientation(1);body.addView(devices);IntentFilter f=new IntentFilter(BluetoothDevice.ACTION_FOUND);f.addAction(BluetoothAdapter.ACTION_DISCOVERY_FINISHED);registerReceiver(receiver,f);registered=true;}
 boolean ready(){if(bt==null||!bt.isEnabled()){status.setText("Bluetooth kapalı veya desteklenmiyor");return false;}return true;}
 void scan(){if(!ready())return;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION},9);return;}seen.clear();draw();bt.cancelDiscovery();status.setText(bt.startDiscovery()?"Taranıyor…":"Tarama başlatılamadı");}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==9&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)scan();}
 void bonded(){if(!ready())return;seen.clear();for(BluetoothDevice d:bt.getBondedDevices())seen.put(d.getAddress(),d);draw();status.setText(seen.size()+" eşleşmiş cihaz");}
 void draw(){devices.removeAllViews();for(BluetoothDevice d:seen.values()){String name=d.getName();button(devices,(name==null?"Bilinmeyen":name)+" • "+d.getAddress(),()->new AlertDialog.Builder(this).setTitle("Bu cihazla eşleş?").setMessage("Yalnızca izinli cihaz. Tek istek gönderilir.").setNegativeButton("İptal",null).setPositiveButton("Eşleş",(x,y)->{bt.cancelDiscovery();try{status.setText(d.createBond()?"Eşleşme isteği gönderildi":"Eşleşme başlatılamadı");}catch(Exception e){status.setText("Eşleşme hatası");}}).show());}}
 void advertise(){if(!ready())return;BluetoothLeAdvertiser a=bt.getBluetoothLeAdvertiser();if(a==null||!bt.isMultipleAdvertisementSupported()){status.setText("Bu donanım BLE reklam yayını desteklemiyor");return;}if(ads.size()>=3){status.setText("En fazla 3 test yayını");return;}final int number=ads.size()+1;AdvertiseCallback cb=new AdvertiseCallback(){public void onStartSuccess(AdvertiseSettings s){status.setText("CHAOS test yayını "+number+" aktif (30 sn)");}public void onStartFailure(int e){ads.remove(this);status.setText("BLE hata: "+e);}};ads.add(cb);try{a.startAdvertising(new AdvertiseSettings.Builder().setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_POWER).setConnectable(false).setTimeout(30000).build(),new AdvertiseData.Builder().addServiceUuid(new ParcelUuid(UUID.fromString(String.format(Locale.US,"0000ca0%d-0000-1000-8000-00805f9b34fb",number)))).build(),cb);}catch(Exception e){ads.remove(cb);status.setText("BLE başlatılamadı");}}
 void message(){EditText e=new EditText(this);new AlertDialog.Builder(this).setTitle("TXT mesajını yaz").setView(e).setNegativeButton("İptal",null).setPositiveButton("Paylaş",(d,w)->{try{java.io.File f=new java.io.File(getCacheDir(),"Mesaj.txt");try(java.io.FileOutputStream o=new java.io.FileOutputStream(f)){o.write(e.getText().toString().getBytes("UTF-8"));}android.net.Uri u=android.net.Uri.parse("content://net.j5os.chaoscontrol.message/Mesaj.txt");Intent i=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("Mesaj.txt",u));startActivity(Intent.createChooser(i,"Bluetooth ile paylaş"));}catch(Exception x){status.setText("Mesaj gönderilemedi");}}).show();}
 void stop(){if(bt!=null&&bt.isEnabled()){bt.cancelDiscovery();BluetoothLeAdvertiser a=bt.getBluetoothLeAdvertiser();if(a!=null)for(AdvertiseCallback c:ads)a.stopAdvertising(c);}ads.clear();status.setText("BT testleri durdu");}
 @Override protected void onDestroy(){stop();if(registered)unregisterReceiver(receiver);super.onDestroy();}
}
